using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace MacroExecute {
internal static class MouseClickTests {
static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
static Task NoWait(int ms,CancellationToken t){t.ThrowIfCancellationRequested();return Task.FromResult(true);}
public static void Run(Action<string,Action> test,string directory){
test("Modified clicks cover every modifier combination button and click count",delegate{
foreach(MouseButton button in Enum.GetValues(typeof(MouseButton)))for(int flags=0;flags<8;flags++)for(int count=1;count<=3;count++)using(var d=new TestDesktop()){
var events=new List<string>();var waits=new List<int>();var k=new TestKeyboard();k.OnEvent=events.Add;d.OnEvent=events.Add;var h=new WindowsHost(null,d,k,new TestClipboard());h.Wait=delegate(int ms,CancellationToken t){waits.Add(ms);return NoWait(ms,t);};h.Execute(new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.CurrentPointer,Button=button,MouseModifiers=(MouseModifiers)flags,ClickCount=count},CancellationToken.None).GetAwaiter().GetResult();
var expected=new List<string>();var keys=new List<int>();foreach(int key in new[]{17,16,18})if((flags&(key==17?1:key==16?2:4))!=0){keys.Add(key);expected.Add("down:"+key);}for(int i=0;i<count;i++){expected.Add("mouse:down:"+button);expected.Add("mouse:up:"+button);}keys.Reverse();expected.AddRange(keys.Select(key=>"up:"+key));Check(events.SequenceEqual(expected),"Wrong input order");Check(waits.Count==count*2-1&&waits.Where((n,i)=>i%2==0).All(n=>n==30)&&waits.Where((n,i)=>i%2==1).All(n=>n==100),"Wrong timing");h.ReleaseInputs();Check(events.SequenceEqual(expected),"Released already released input");}
});
test("Cancellation during click or gap releases owned inputs in reverse order",delegate{for(int stop=1;stop<=2;stop++)using(var d=new TestDesktop())using(var c=new CancellationTokenSource()){int calls=0;var events=new List<string>();var k=new TestKeyboard();k.OnEvent=events.Add;d.OnEvent=events.Add;var h=new WindowsHost(null,d,k,new TestClipboard());h.Wait=delegate(int ms,CancellationToken t){if(++calls==stop)c.Cancel();return NoWait(ms,t);};bool canceled=false;try{h.Execute(new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.CurrentPointer,MouseModifiers=(MouseModifiers)7,ClickCount=3},c.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){canceled=true;}Check(canceled&&d.Clicks.Count==1&&events.Skip(events.Count-4).SequenceEqual(new[]{"mouse:up:Left","up:18","up:16","up:17"}),"Cancellation leaked input");}});
test("Previously held physical and macro modifiers remain held",delegate{foreach(int key in new[]{17,162,163,16,160,161,18,164,165})foreach(bool physical in new[]{true,false})using(var d=new TestDesktop()){var k=new TestKeyboard();var h=new WindowsHost(null,d,k,new TestClipboard());h.Wait=NoWait;if(physical)k.Held.Add(key);else h.Execute(new Step{Kind=ActionKind.KeyDown,KeyCode=key},CancellationToken.None).GetAwaiter().GetResult();k.Events.Clear();h.Execute(new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.CurrentPointer,MouseModifiers=(MouseModifiers)7},CancellationToken.None).GetAwaiter().GetResult();Check(k.Held.Contains(key)&&!k.Events.Contains("up:"+key),"Preheld key released");h.ReleaseInputs();Check(k.Held.Contains(key)==physical,"Cleanup changed physical key ownership");}});
test("Click failure attempts every release and cleanup retries failed releases",delegate{using(var d=new TestDesktop()){var events=new List<string>();var k=new TestKeyboard();bool fail=true;k.OnEvent=delegate(string e){events.Add(e);if(e=="up:18"&&fail)throw new InvalidOperationException("release");};d.OnEvent=delegate(string e){events.Add(e);if(e=="mouse:down:Left")throw new InvalidOperationException("mouse failure");};var h=new WindowsHost(null,d,k,new TestClipboard());h.Wait=NoWait;try{h.Execute(new Step{Kind=ActionKind.MouseClick,Pointer=PointerMode.CurrentPointer,MouseModifiers=(MouseModifiers)7},CancellationToken.None).GetAwaiter().GetResult();throw new Exception("Failure swallowed");}catch(InvalidOperationException e){Check(e.Message=="mouse failure","Original error masked");}Check(events.Contains("mouse:up:Left")&&events.Contains("up:16")&&events.Contains("up:17"),"Release aborted");fail=false;h.ReleaseInputs();Check(events.Count(e=>e=="up:18")==2,"Failed release not retried");}});
test("Click settings migrate legacy files and roundtrip new settings",delegate{var legacy=Storage.Decode("{\"SchemaVersion\":1,\"Steps\":[{\"Kind\":8}]}").Steps[0];Check(legacy.ClickCount==1&&legacy.ClickIntervalMs==100&&legacy.MouseModifiers==MouseModifiers.None,"Legacy defaults changed");var step=new Step{Kind=ActionKind.MouseClick,MouseModifiers=MouseModifiers.Alt,ClickCount=3,ClickIntervalMs=250,InputHoldMs=750};var loaded=Storage.Decode(Storage.Encode(new Macro{Steps=new List<Step>{step}})).Steps[0];Check(loaded.Clone().MouseModifiers==MouseModifiers.Alt&&loaded.ClickCount==3&&loaded.InputHoldMs==750&&loaded.ClickIntervalMs==250,"Settings lost");});
test("Invalid modified click settings are rejected",delegate{foreach(var s in new[]{new Step{ClickCount=0},new Step{ClickCount=4},new Step{ClickIntervalMs=-1},new Step{MouseModifiers=(MouseModifiers)8},new Step{Kind=ActionKind.Delay,MouseModifiers=MouseModifiers.Alt}}){bool rejected=false;try{Storage.Validate(new Macro{Steps=new List<Step>{s}});}catch(InvalidDataException){rejected=true;}Check(rejected,"Invalid click setting accepted");}});
test("Image clicks acquire modifiers only after a successful match",delegate{foreach(bool found in new[]{true,false})using(var d=new TestDesktop()){var k=new TestKeyboard();if(!found)d.AppearAfter=int.MaxValue;var h=new WindowsHost(null,d,k,new TestClipboard());h.Wait=NoWait;using(var b=new System.Drawing.Bitmap(2,2)){b.SetPixel(0,0,System.Drawing.Color.Red);b.SetPixel(1,0,System.Drawing.Color.Black);b.SetPixel(0,1,System.Drawing.Color.Black);b.SetPixel(1,1,System.Drawing.Color.Lime);var s=new Step{Kind=ActionKind.ClickImage,ImageData=ImageTemplate.Encode(b),MouseModifiers=MouseModifiers.Alt,ClickCount=2,TimeoutMs=10,PollMs=5};try{h.Execute(s,CancellationToken.None).GetAwaiter().GetResult();}catch(TimeoutException){Check(!found,"Image should match");}Check(d.Clicks.Count==(found?2:0)&&k.Events.Count==(found?2:0),"Missing image sent input or matched click failed");}}});
test("Modified click editors render hidden in every palette",delegate{foreach(string style in UiTheme.Styles)foreach(bool dark in new[]{true,false}){UiTheme.Style=style;UiTheme.Dark=dark;foreach(var kind in new[]{ActionKind.MouseClick,ActionKind.ClickImage})using(var editor=new StepEditor(new Step{Kind=kind,MouseModifiers=MouseModifiers.Alt,ClickCount=3},directory)){editor.Size=editor.MinimumSize;HeadlessUi.Render(editor,Path.Combine(directory,"click-"+kind+"-"+style+"-"+dark+".png"));Check(!editor.Visible,"Click editor shown");}}UiTheme.Style="Aftershock";UiTheme.Dark=true;});
}
}
}


